            new() { Id = 8, Title = "Creative Writing", Code = "ENG 210", Description = "Workshop-based course in fiction and poetry writing with peer critique.", Credits = 3, Schedule = "Tue/Thu 3:00–4:15 PM", InstructorName = "Prof. Hannah Brooks", InstructorBio = "Prof. Brooks is a published novelist and poet with three National Book Award nominations.", DepartmentId = 4, DepartmentName = "English", IsFeatured = false },
