@page "/"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject ICatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="hero">
    <h1>University Course Catalog</h1>
    <p>Explore our departments and courses. Find the right classes for your academic journey.</p>
</div>

<section class="featured-section">
    <h2>Featured Courses</h2>
    <div class="course-grid">
        @foreach (var course in _featuredCourses)
        {
            <div class="course-card">
                <span class="badge">@course.Code</span>
                <h3><a href="/courses/@course.Id">@course.Title</a></h3>
                <p>@course.Credits credits &middot; @course.DepartmentName</p>
                <p class="instructor">@course.InstructorName</p>
            </div>
        }
    </div>
</section>

<section class="departments-section">
    <h2>Departments</h2>
    <div class="dept-grid">
        @foreach (var dept in _departments)
        {
            <div class="dept-card">
                <h3><a href="/courses?departmentId=@dept.Id">@dept.Name</a></h3>
                <p>@dept.Description</p>
            </div>
        }
    </div>
</section>

@code {
    private IReadOnlyList<Course> _featuredCourses = [];
    private IReadOnlyList<Department> _departments = [];

    protected override void OnInitialized()
    {
        _featuredCourses = CatalogService.GetFeaturedCourses();
        _departments = CatalogService.GetDepartments();
    }
}

@page "/courses"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject ICatalogService CatalogService

<PageTitle>Course Catalog - Browse Courses</PageTitle>

<h1>Browse Courses</h1>

<form method="get" class="filter-form">
    <div class="filter-row">
        <input type="text" name="search" value="@Search" placeholder="Search by title, code, or instructor..." class="search-input" />
        <select name="departmentId" class="dept-select">
            <option value="">All Departments</option>
            @foreach (var dept in _departments)
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
        <button type="submit" class="btn btn-primary">Search</button>
    </div>
</form>

@if (_courses.Count == 0)
{
    <p class="no-results">No courses found matching your criteria.</p>
}
else
{
    <table class="course-table">
        <thead>
            <tr>
                <th>Code</th>
                <th>Title</th>
                <th>Department</th>
                <th>Credits</th>
                <th>Instructor</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in _courses)
            {
                <tr>
                    <td>@course.Code</td>
                    <td>@course.Title</td>
                    <td>@course.DepartmentName</td>
                    <td>@course.Credits</td>
                    <td>@course.InstructorName</td>
                    <td><a href="/courses/@course.Id" class="btn btn-sm">Details</a></td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }

    private IReadOnlyList<Department> _departments = [];
    private IReadOnlyList<Course> _courses = [];

    protected override void OnInitialized()
    {
        _departments = CatalogService.GetDepartments();
        _courses = CatalogService.GetCourses(Search, DepartmentId);
    }
}

@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject ICatalogService CatalogService

@if (_course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <h1>Course Not Found</h1>
    <p>The requested course could not be found. <a href="/courses">Back to catalog</a></p>
}
else
{
    <PageTitle>@_course.Title - Course Catalog</PageTitle>

    <nav class="breadcrumb">
        <a href="/">Home</a> &rsaquo;
        <a href="/courses?departmentId=@_course.DepartmentId">@_course.DepartmentName</a> &rsaquo;
        <span>@_course.Code</span>
    </nav>

    <article class="course-detail">
        <header>
            <h1>@_course.Title</h1>
            <span class="badge">@_course.Code</span>
        </header>

        <section class="detail-grid">
            <div class="detail-main">
                <h2>Description</h2>
                <p>@_course.Description</p>

                <h2>Instructor</h2>
                <h3>@_course.InstructorName</h3>
                <p>@_course.InstructorBio</p>
            </div>

            <aside class="detail-sidebar">
                <dl>
                    <dt>Credits</dt>
                    <dd>@_course.Credits</dd>

                    <dt>Schedule</dt>
                    <dd>@_course.Schedule</dd>

                    <dt>Department</dt>
                    <dd>@_course.DepartmentName</dd>
                </dl>
                <a href="/enroll?courseId=@_course.Id" class="btn btn-primary btn-block">Enroll in This Course</a>
            </aside>
        </section>
    </article>
}

@code {
    [Parameter] public int Id { get; set; }

    private Course? _course;

    protected override void OnInitialized()
    {
        _course = CatalogService.GetCourse(Id);
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject ICatalogService CatalogService

<PageTitle>Enrollment Request - Course Catalog</PageTitle>

<h1>Enrollment Request</h1>

@if (_submitted)
{
    <div class="success-message">
        <h2>Request Submitted</h2>
        <p>Thank you, <strong>@_model.StudentName</strong>. Your enrollment request for <strong>@_selectedCourseName</strong> has been received. You will be notified once it is processed.</p>
        <a href="/courses" class="btn btn-primary">Back to Course Catalog</a>
    </div>
}
else
{
    <p>Fill out the form below to request enrollment in a course.</p>

    <form method="post" @formname="enrollment" @onsubmit="HandleSubmit" class="enroll-form">
        <AntiforgeryToken />

        <div class="form-group">
            <label for="studentName">Full Name</label>
            <input type="text" id="studentName" name="_model.StudentName" value="@_model.StudentName" required maxlength="100" />
        </div>

        <div class="form-group">
            <label for="studentId">Student ID</label>
            <input type="text" id="studentId" name="_model.StudentId" value="@_model.StudentId" required maxlength="20" pattern="[A-Za-z0-9]+" title="Alphanumeric characters only" />
        </div>

        <div class="form-group">
            <label for="courseId">Course</label>
            <select id="courseId" name="_model.CourseId" required>
                <option value="">-- Select a Course --</option>
                @foreach (var course in _courses)
                {
                    <option value="@course.Id" selected="@(course.Id == _model.CourseId)">@course.Code - @course.Title</option>
                }
            </select>
        </div>

        <button type="submit" class="btn btn-primary">Submit Request</button>
    </form>
}

@code {
    [SupplyParameterFromQuery] public int? CourseId { get; set; }

    [SupplyParameterFromForm] private EnrollmentRequest _model { get; set; } = new();

    private IReadOnlyList<Course> _courses = [];
    private bool _submitted;
    private string _selectedCourseName = string.Empty;

    protected override void OnInitialized()
    {
        _courses = CatalogService.GetCourses();

        if (!_submitted && CourseId.HasValue && _model.CourseId == 0)
        {
            _model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        var course = CatalogService.GetCourse(_model.CourseId);
        _selectedCourseName = course?.Title ?? "Unknown Course";
        CatalogService.SubmitEnrollmentRequest(_model);
        _submitted = true;
    }
}

